// Form seviyesinde değişkenler
int gizliSayi = 42;
int denemeSayisi = 0;

private void btnTahminEt_Click(object sender, EventArgs e)
{
    try
    {
        int tahmin = Convert.ToInt32(txtTahmin.Text);
        denemeSayisi++;

        if (tahmin == gizliSayi)
        {
            lblIpucu.Text = "🎉 TEBRİKLER! " + denemeSayisi + ". denemede BİLDİNİZ!";
            this.BackColor = Color.LightGreen;
            btnTahminEt.Enabled = false; // Oyunu bitir
        }
        else if (tahmin < gizliSayi)
        {
            lblIpucu.Text = "⬆️ Daha BÜYÜK bir sayı söyle!";
            this.BackColor = Color.LightSalmon;
        }
        else
        {
            lblIpucu.Text = "⬇️ Daha KÜÇÜK bir sayı söyle!";
            this.BackColor = Color.LightSkyBlue;
        }
        txtTahmin.Clear();
        txtTahmin.Focus();
    }
    catch { MessageBox.Show("Lütfen geçerli bir sayı giriniz!"); }
}

